/**
 * GET /api/auth/sessions/[id]/revoke?token=<revocation_token>
 *
 * One-click session revocation from the suspicious-login alert email.
 *
 * This endpoint is intentionally unauthenticated (no session cookie needed)
 * because the user clicking the link in their email may not be logged in on
 * that device. Authentication is provided by the time-limited HMAC token
 * generated by {@link generateRevocationToken} in loginSecurityEmail.ts.
 *
 * Flow:
 *   1. Validate the token (HMAC + expiry)
 *   2. Verify the session ID in the token matches the route param
 *   3. Soft-delete the session (revokedAt = now)
 *   4. Redirect to /login with a confirmation query param
 *
 * Security properties:
 *   - Token is HMAC-signed with NEXTAUTH_SECRET — cannot be forged
 *   - Token encodes an expiry timestamp — replays rejected after 48 h
 *   - Token encodes the session ID — cannot be used to revoke other sessions
 *   - Constant-time HMAC comparison — no timing oracle
 */

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/app/lib/prisma";
import { validateRevocationToken } from "@/app/lib/loginSecurityEmail";
import { createAuditEvent } from "@/app/lib/auditLog";
import { logger } from "@/app/lib/logger";

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id: sessionId } = await params;
  const appUrl =
    process.env.NEXTAUTH_URL ?? process.env.NEXT_PUBLIC_APP_URL ?? "";

  const token = req.nextUrl.searchParams.get("token");

  if (!token) {
    return NextResponse.redirect(
      `${appUrl}/login?revoke=invalid`,
    );
  }

  const validSessionId = validateRevocationToken(token);

  if (!validSessionId || validSessionId !== sessionId) {
    logger.warn("[SessionRevoke] Invalid or expired revocation token", {
      sessionId,
    });
    return NextResponse.redirect(`${appUrl}/login?revoke=invalid`);
  }

  try {
    const result = await prisma.userSession.updateMany({
      where: { id: sessionId, revokedAt: null },
      data: { revokedAt: new Date() },
    });

    if (result.count === 0) {
      // Already revoked — treat as success so the user isn't confused
      return NextResponse.redirect(`${appUrl}/login?revoke=already_revoked`);
    }

    // Fetch userId for the audit trail (session may belong to any user)
    const revokedSession = await prisma.userSession.findUnique({
      where: { id: sessionId },
      select: { userId: true },
    });

    if (revokedSession?.userId) {
      await createAuditEvent({
        actorId: revokedSession.userId,
        action: "session.revoked_via_email",
        resource: "session",
        resourceId: sessionId,
        ipAddress:
          req.headers.get("x-forwarded-for")?.split(",")[0].trim() ||
          req.headers.get("x-real-ip") ||
          "unknown",
        userAgent: req.headers.get("user-agent") || "unknown",
        status: "success",
        metadata: { method: "email_revocation_link" },
      });
    }

    logger.info("[SessionRevoke] Session revoked via email link", { sessionId });
    return NextResponse.redirect(`${appUrl}/login?revoke=success`);
  } catch (error) {
    logger.error("[SessionRevoke] Failed to revoke session", { sessionId, error });
    return NextResponse.redirect(`${appUrl}/login?revoke=error`);
  }
}
